const config = $input.first().json;
const username = String(config.username || '').trim().replace(/^@/, '');
if (!username || username === 'YOUR_TRACKED_USERNAME' || !/^[A-Za-z0-9_][A-Za-z0-9_.]{0,29}$/.test(username)) {
  throw new Error('Set username to an account already tracked in your Instoryview account (without @).');
}
const list = config.list;
if (!['followers', 'following'].includes(list)) throw new Error('list must be followers or following.');
const parseDate = (value, field) => {
  if (typeof value !== 'string' || !/^\d{4}-\d{2}-\d{2}$/.test(value)) throw new Error(field + ' must be YYYY-MM-DD.');
  const date = new Date(value + 'T00:00:00.000Z');
  if (!Number.isFinite(date.getTime()) || date.toISOString().slice(0, 10) !== value) throw new Error(field + ' is not a valid calendar date.');
  return date.getTime();
};
const start = parseDate(config.from, 'from');
const end = parseDate(config.to, 'to');
if (end < start || (end - start) / 86400000 + 1 > 366) throw new Error('Use an inclusive date range of 1 to 366 days.');
if (typeof config.timezone !== 'string' || !config.timezone) throw new Error('Set an IANA timezone such as UTC or America/New_York.');
try { new Intl.DateTimeFormat('en', { timeZone: config.timezone }).format(new Date()); }
catch { throw new Error('timezone must be a valid IANA timezone.'); }
const changesUrl = 'https://instoryview.com/open-api/v1/accounts/' + encodeURIComponent(username) + '/changes';
const query = [['list', list], ['from', config.from], ['to', config.to], ['timezone', config.timezone], ['limit', '100']]
  .map(([key, value]) => key + '=' + encodeURIComponent(value)).join('&');
return [{ json: { username, list, from: config.from, to: config.to, timezone: config.timezone,
  changesUrl, initialUrl: changesUrl + '?' + query }, pairedItem: { item: 0 } }];

const pages = $input.all().map(item => item.json);
const config = $('Validate settings').first().json;
if (!pages.length) throw new Error('Instoryview returned no response pages.');
if (pages.length > 100) throw new Error('The export exceeds the 100-page limit; reduce the date range.');
const headers = ['tracked_account_id', 'tracked_username', 'list', 'event_id', 'change_kind', 'detected_at', 'account_id', 'account_username', 'profile_url', 'coverage', 'data_as_of'];
const summaryKeys = ['added', 'removed', 'netDiscovered', 'countNetChange'];
const requireString = (value, label) => {
  if (typeof value !== 'string' || !value) throw new Error('Invalid Instoryview response: ' + label + ' must be a nonempty string.');
  return value;
};
const safeCell = value => {
  const text = value == null ? '' : String(value);
  // Protect spreadsheet formula interpretation, including leading whitespace/control characters.
  return /^[\t\r\n]/.test(text) || /^\s*[=+\-@]/.test(text) ? "'" + text : text;
};
const first = pages[0];
if (!first.data || !first.meta || !first.data.summary || typeof first.data.summary !== 'object') throw new Error('Invalid Instoryview response envelope.');
const rangeSummary = {};
for (const key of summaryKeys) {
  const value = first.data.summary[key];
  if (value !== null && (typeof value !== 'number' || !Number.isFinite(value))) throw new Error('Invalid summary value: ' + key + '. Unknown values must remain null.');
  rangeSummary[key] = value;
}
const trackedAccountId = requireString(first.data.accountId, 'accountId');
const seenIds = new Set();
const rows = [];
const pageObservations = [];
const warnings = [];
const allowedKinds = config.list === 'followers' ? ['new_follower', 'lost_follower'] : ['new_follow', 'unfollow'];
for (let index = 0; index < pages.length; index++) {
  const page = pages[index];
  const data = page.data;
  const meta = page.meta;
  if (!data || !meta || !Array.isArray(data.items) || !Array.isArray(meta.warnings)) throw new Error('Invalid response on page ' + (index + 1) + '.');
  if (data.accountId !== trackedAccountId || data.username?.toLowerCase() !== config.username.toLowerCase() || data.list !== config.list || data.from !== config.from || data.to !== config.to || data.timezone !== config.timezone) {
    throw new Error('Instoryview changed the selected account or range during pagination.');
  }
  if (meta.source !== 'tracking_history' || meta.creditsUsed !== 0) throw new Error('Expected a zero-credit tracking_history read.');
  if (!['partial', 'unknown', 'complete'].includes(meta.coverage)) throw new Error('Invalid coverage on page ' + (index + 1) + '.');
  requireString(meta.requestId, 'requestId');
  if (meta.asOf !== null && (typeof meta.asOf !== 'string' || !Number.isFinite(Date.parse(meta.asOf)))) throw new Error('asOf must be a timestamp string or null.');
  if (typeof meta.hasMore !== 'boolean') throw new Error('Missing hasMore on page ' + (index + 1) + '.');
  if (meta.hasMore && (typeof meta.nextCursor !== 'string' || !meta.nextCursor)) throw new Error('hasMore requires nextCursor on page ' + (index + 1) + '.');
  if (!meta.hasMore && meta.nextCursor != null) throw new Error('A final page must not contain nextCursor.');
  if (index < pages.length - 1 && !meta.hasMore) throw new Error('Received pages after the final page.');
  if (index === pages.length - 1 && meta.hasMore) throw new Error('Export is incomplete at the 100-page limit. Reduce the date range and rerun; no CSV was created.');
  for (const key of summaryKeys) {
    if (data.summary?.[key] !== rangeSummary[key]) throw new Error('Range summary changed during pagination; rerun the export.');
  }
  pageObservations.push({ page: index + 1, requestId: meta.requestId, asOf: meta.asOf, coverage: meta.coverage, warnings: meta.warnings });
  warnings.push(...meta.warnings);
  for (const event of data.items) {
    if (!event || !allowedKinds.includes(event.kind) || !event.account) throw new Error('Unexpected change event on page ' + (index + 1) + '.');
    const eventId = requireString(event.id, 'event.id');
    if (seenIds.has(eventId)) throw new Error('Duplicate change event across pages; rerun the export.');
    seenIds.add(eventId);
    const accountId = requireString(event.account.id, 'event.account.id');
    const detectedAt = requireString(event.detectedAt, 'event.detectedAt');
    if (!Number.isFinite(Date.parse(detectedAt))) throw new Error('Invalid detectedAt for event ' + eventId + '.');
    if (event.account.username !== null && typeof event.account.username !== 'string') throw new Error('Invalid account username for event ' + eventId + '.');
    const accountUsername = event.account.username;
    rows.push({ tracked_account_id: safeCell(trackedAccountId), tracked_username: safeCell(data.username), list: data.list,
      event_id: safeCell(eventId), change_kind: event.kind, detected_at: detectedAt, account_id: safeCell(accountId),
      account_username: safeCell(accountUsername), profile_url: accountUsername ? 'https://www.instagram.com/' + encodeURIComponent(accountUsername) + '/' : '',
      coverage: meta.coverage, data_as_of: meta.asOf });
  }
}
const coverages = pageObservations.map(page => page.coverage);
const coverage = coverages.includes('unknown') ? 'unknown' : coverages.includes('partial') ? 'partial' : 'complete';
const summary = { accountId: trackedAccountId, username: first.data.username, list: config.list, from: config.from, to: config.to,
  timezone: config.timezone, ...rangeSummary, exportedEvents: rows.length, pagesRead: pages.length, source: 'tracking_history',
  creditsUsed: 0, asOf: first.meta.asOf, coverage, warnings, pageObservations,
  timeMeaning: 'detectedAt is when Instoryview detected a change, not the exact Instagram action time.',
  coverageMeaning: 'All response pages were fetched. Coverage describes retained tracking history, which may be partial or unknown.' };
const fileName = 'instoryview-' + config.list + '-' + config.username + '-' + config.from + '-to-' + config.to + '.csv';
return [{ json: { summary, rows, headers, fileName }, pairedItem: pages.map((_, item) => ({ item })) }];

const input = $input.first().json;
const csv = input.headers.join(',') + '\r\n';
const data = await this.helpers.prepareBinaryData(Buffer.from(csv, 'utf8'), input.fileName, 'text/csv');
return [{ json: { ...input.summary, fileName: input.fileName, empty: true }, binary: { data }, pairedItem: { item: 0 } }];
